import{_ as e,c as i,o as t,ag as r}from"./chunks/framework.DfL_BkQ-.js";const d=JSON.parse('{"title":"プライバシーの選択","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/privacy-choices.md","filePath":"ja/guide/privacy-choices.md","lastUpdated":1794112334000}'),s={name:"ja/guide/privacy-choices.md"};function o(c,a,l,p,h,n){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="プライバシーの選択" tabindex="-1">プライバシーの選択 <a class="header-anchor" href="#プライバシーの選択" aria-label="Permalink to &quot;プライバシーの選択&quot;">​</a></h1><p>本ページでは、Nicasa へのプライバシー請求の送信方法と、その後に期待できる対応について説明します。</p><h2 id="対象となる内容" tabindex="-1">対象となる内容 <a class="header-anchor" href="#対象となる内容" aria-label="Permalink to &quot;対象となる内容&quot;">​</a></h2><p>本ページは、個人データへのアクセス、削除、ポータビリティの請求、または特定のデータ利用からのオプトアウト（該当する場合の「販売しないでください」請求など）に使用できます。</p><p>注記：Nicasa は現在、個人データを収集・保存していません（プライバシーポリシーをご参照ください）。当社があなたに関する個人データを保有しているとお考えの場合は、請求を送信してください。調査いたします。</p><h2 id="請求の送信方法" tabindex="-1">請求の送信方法 <a class="header-anchor" href="#請求の送信方法" aria-label="Permalink to &quot;請求の送信方法&quot;">​</a></h2><p>効率的に処理するため、請求の際に以下の情報をご提供ください：</p><ul><li>お名前</li><li>連絡先メールアドレス</li><li>請求内容の説明（アクセス、削除、ポータビリティ、オプトアウト）</li><li>記録の特定に役立つ情報（サポートチケット ID など）</li></ul><p>請求は以下のいずれかに送信してください：</p><ul><li>メール：nicasa@w3cub.com</li><li>プライバシー issue の作成：<a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a></li></ul><h2 id="回答までの期間" tabindex="-1">回答までの期間 <a class="header-anchor" href="#回答までの期間" aria-label="Permalink to &quot;回答までの期間&quot;">​</a></h2><p>有効な請求には 30 日以内に確認と回答を行うよう努めます。さらに時間が必要な場合は、想定される期間をお知らせします。</p><h2 id="個人データを保有していない場合" tabindex="-1">個人データを保有していない場合 <a class="header-anchor" href="#個人データを保有していない場合" aria-label="Permalink to &quot;個人データを保有していない場合&quot;">​</a></h2><p>Nicasa は画像をローカルで処理し、ユーザーデータを収集しない設計であるため、多くの請求は「個人データを保有していない」旨の確認をもって終了します。個人データが収集された証拠をご提供いただければ、調査し適切な対応を行います。</p><h2 id="販売しないでください-オプトアウト" tabindex="-1">販売しないでください / オプトアウト <a class="header-anchor" href="#販売しないでください-オプトアウト" aria-label="Permalink to &quot;販売しないでください / オプトアウト&quot;">​</a></h2><p>特定の法域の権利（CCPA/CPRA など）に基づきデータの販売からのオプトアウトを行使する場合で、当社があなたの個人データを販売したとお考えの場合は、請求の中で状況を説明してください。個人データを販売していない場合は、その旨を回答で確認します。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>本手続きについてご質問がある場合は、nicasa@w3cub.com までご連絡いただくか、<a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">https://github.com/nicasa-app/nicasa-support/issues</a> で issue を作成してください。</p>',18)])])}const _=e(s,[["render",o]]);export{d as __pageData,_ as default};
